import requests

# Try to access USDA yearbook from 1959
yearbook_url = 'https://archive.org/details/yearbookagriculture1959'
try:
    response = requests.get(yearbook_url, timeout=15)
    if response.status_code == 200:
        print(f'Successfully accessed: {yearbook_url}')
        content = response.text

        # Check if it contains the sections we need
        if 'dried and dehydrated' in content.lower():
            print('*** Contains \"dried and dehydrated\" section ***')
        if 'frozen' in content.lower():
            print('*** Contains \"frozen\" section ***')
        if 'chilled' in content.lower():
            print('*** Contains \"chilled\" section ***')

        # Look for table of contents or index
        if 'contents' in content.lower() or 'table of contents' in content.lower():
            print('*** Contains table of contents ***')

        print(f'Content length: {len(content)} characters')
        print(f'First 500 characters: {content[:500]}')
    else:
        print(f'Failed to access: {yearbook_url} - Status: {response.status_code}')
except Exception as e:
    print(f'Error accessing {yearbook_url}: {e}')
""}

